-- =====================================================================
-- Fehlende Verlage nachtragen (468 Bücher)
-- Nur sichere Fälle:
--   ISBN : die ISBN-Verlagsnummer gehört in Ihrer Datenbank eindeutig zu diesem Verlag
--   Titel: derselbe Titel vom selben Autor ist schon mit diesem Verlag erfasst
-- Betrifft nur Bücher, die (noch) keinen Verlag haben bzw. bei "Unknown",
-- "unbekannt" oder einem __LEGACY__-Eintrag stehen. Wurde ein Verlag inzwischen
-- von Hand eingetragen, wird das Buch übersprungen.
-- Erzeugt am 08.11.2026 aus dem Backup rxlog_2026_11_08.bak (Stand nach allen Verlags-Skripten).
--
-- Probelauf:
--   psql "$DB" -v ON_ERROR_STOP=1 -f buecher_verlag_nachtragen.sql
-- Echt:
--   sed 's/^ROLLBACK;$/COMMIT;/' buecher_verlag_nachtragen.sql | psql "$DB" -v ON_ERROR_STOP=1
-- =====================================================================

BEGIN;

CREATE TEMP TABLE vorschlag (book_id uuid PRIMARY KEY, publisher_id uuid NOT NULL) ON COMMIT DROP;
;

-- "kein Verlag"-Einträge
CREATE TEMP TABLE ohne_verlag (id uuid PRIMARY KEY) ON COMMIT DROP;
    '11108ae2-d78c-4ece-aa61-722e57daaa89',
    'd47a3e05-735e-440e-8b86-cc429551ec60',
    '0d6bd6fb-67f2-4b56-9390-11e74cf73e5f',
    '62d34fbd-a752-476b-84c8-b81e808bf72d',
    '8527a186-2297-4bba-a951-67f194feec36',
    'bd7f50ae-40c9-4abc-8f44-3d2372ac088f',
    'c4612683-1a44-4430-a202-1fb36ba0639a',
    'b164def1-747c-4e07-be2d-4aa48566a0f9',
    'c72100f3-4930-4c47-adf3-a668aa0c76e7',
    '21cd5b22-7bac-402d-88af-0a53589bb44b',
    'd7288cff-fb7c-4386-bc81-16916adbfd7d',
    'dde6418e-d337-4f2d-bc18-60a62b4657c8',
    '8dc08e9f-3f41-4fd7-817c-f691cb38e56d',
    'ddbb58cc-9e3f-4d10-9677-9125b3c045c2',
    '91712c2a-443d-41a1-a29f-ca5245a41ef9',
    '675b5077-a380-4089-86b9-5fb212930aa8'
]::uuid[]);

-- ---- Sicherheitsprüfung ----------------------------------------------
DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM vorschlag v WHERE NOT EXISTS (SELECT 1 FROM publishers p WHERE p.id = v.publisher_id);
  IF n > 0 THEN RAISE EXCEPTION '% vorgeschlagene Verlage existieren nicht – bitte Liste neu erzeugen', n; END IF;
END $$;

-- ---- Sicherung -------------------------------------------------------
CREATE TABLE IF NOT EXISTS books_publisher_nachtrag_20261108
  (book_id uuid, old_publisher_id uuid, new_publisher_id uuid, changed_at timestamptz DEFAULT now());
  SELECT b.id, b.publisher_id, v.publisher_id
  FROM books b JOIN vorschlag v ON v.book_id = b.id
  WHERE b.publisher_id IS NULL OR b.publisher_id IN (SELECT id FROM ohne_verlag);

-- ---- Verlag eintragen ------------------------------------------------
UPDATE books b SET publisher_id = v.publisher_id
FROM vorschlag v
WHERE b.id = v.book_id
  AND (b.publisher_id IS NULL OR b.publisher_id IN (SELECT id FROM ohne_verlag));

-- ---- Ergebnis ----------------------------------------------------------
SELECT 'Verlag eingetragen' AS was, count(*) AS anzahl
  FROM books_publisher_nachtrag_20261108 WHERE changed_at >= now() - interval '1 minute'
UNION ALL
SELECT 'übersprungen (Verlag inzwischen vorhanden oder Buch fehlt)', count(*)
  FROM vorschlag v WHERE NOT EXISTS (SELECT 1 FROM books_publisher_nachtrag_20261108 x
                                     WHERE x.book_id = v.book_id AND x.changed_at >= now() - interval '1 minute')
UNION ALL
SELECT 'Bücher weiterhin ohne Verlag', count(*)
  FROM books WHERE publisher_id IS NULL OR publisher_id IN (SELECT id FROM ohne_verlag);

SELECT coalesce(p.abbr, p.name) AS kuerzel, p.name_display AS verlag, count(*) AS nachgetragen
FROM books_publisher_nachtrag_20261108 x JOIN publishers p ON p.id = x.new_publisher_id
WHERE x.changed_at >= now() - interval '1 minute'
GROUP BY 1, 2 ORDER BY 3 DESC LIMIT 15;

-- Probelauf: nichts wird gespeichert. Für den echten Lauf durch COMMIT; ersetzen.
ROLLBACK;
